const main=document.querySelector('main'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let DATA,items=[],civs=[],sources={},state,storage,liveMap=null,markers=[],mapIndex=FRAMES.indexOf(850),currentType='all',quizAnswers={},toastTimer;
const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const CIV_COLORS={egypt:'#e6b450',greece:'#4fa3e3',rome:'#e0564f',china:'#f08a3c',umayyad:'#efe6cf',abbasid:'#a48cff',andalus:'#2ec4b0','first-saudi':'#5cc172',persia:'#d16ba5',ottoman:'#ff6b6b',saba:'#b5d65a',nabataea:'#ee8aa6',mamluks:'#f2c14e',mongols:'#64b5f6',rashidun:'#4dd0e1',byzantine:'#e8746a',sasanian:'#c49a6c',fatimids:'#f6d55c',ayyubids:'#ffb74d',seljuks:'#81c784',safavids:'#4db6ac',mughals:'#f48fb1','second-saudi':'#43a047','saudi-kingdom':'#2e7d32',parthians:'#ba68c8',almohads:'#26a69a',mali:'#ffca28',ming:'#ef5350'};const civColor=id=>CIV_COLORS[id]||'#d6b477';
const ERAS=[[-500,'العالم القديم'],[500,'العصر الكلاسيكي'],[1250,'العصور الإسلامية'],[1500,'عصر المغول والمماليك'],[Infinity,'بدايات العصر الحديث']];const eraName=y=>ERAS.find(e=>y<e[0])[1];
const KINDS={battle:'معركة أو حصار',founding:'تأسيس وبناء',political:'تحول سياسي'};
const certLevel=x=>{const c=x?.certainty||'';return /تقريب/.test(c)?['approx','تاريخ أو موضع تقريبي']:/^موثق/.test(c)?['sure','موثق بالمصادر']:['mixed','التوثيق متفاوت بين الأقسام']};
const types={civilization:'حضارة ودولة',city:'مدينة',person:'شخصية',event:'حدث',science:'علوم واكتشافات'};
try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}state=readStore(storage);
const byId=id=>items.find(x=>x.id===id);
const href=id=>`#/topic/${encodeURIComponent(id)}`;
const sourceLinks=ids=>`<ul class="source-list">${[...new Set(ids||[])].map((id,i)=>sources[id]?`<li id="src-${escape(id)}"><b class="src-n">${i+1}</b><a href="${escape(sources[id].url)}" target="_blank" rel="noopener noreferrer">${escape(sources[id].title)} ↗</a><small>${escape(sources[id].type||'مصدر تاريخي')} · اطلعنا عليه في 12 أكتوبر 2026</small></li>`:'').join('')}</ul>`;
function persist(){const ok=saveStore(storage,state);if(!ok)toast('تعذر حفظ التقدم على هذا المتصفح؛ سيبقى لهذه الجلسة فقط.');return ok}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3800)}
const head=(title,description,eyebrow='اكتشف. اربط. افهم.')=>`<div class="container page-head reveal"><div class="breadcrumb"><a href="#/">الرئيسية</a> / ${escape(title)}</div><div class="eyebrow">${eyebrow}</div><h1>${escape(title)}</h1><p>${escape(description)}</p></div>`;
const figure=x=>x.image?`<figure class="photo"><img src="${escape(x.image.src)}" alt="${escape(x.image.caption)}" loading="lazy" decoding="async" onerror="this.closest('figure').remove()"><figcaption>${escape(x.image.caption)} · <a href="${escape(x.image.page)}" target="_blank" rel="noopener">${escape(x.image.author)} / ${escape(x.image.license)}</a></figcaption></figure>`:'';
function card(c){return `<a class="civ-card ${c.image?'has-photo':''}" href="${href(c.id)}"${c.image?` style="--photo:url('${escape(c.image.src)}')"`:''}>${c.image?'<span class="card-photo" aria-hidden="true"></span>':motif(c.id)}<small>${escape(c.region)}</small><h3>${escape(c.title)}</h3><small>${escape(c.periodLabel)}</small></a>`}
function result(x){return `<a class="result-card" href="${href(x.id)}"><span class="badge">${types[x.type]||'موضوع'}</span><h3>${escape(x.title)}</h3><p>${escape(x.summary.slice(0,170))}${x.summary.length>170?'…':''}</p></a>`}
function sectionTitle(n,title,desc,link,label){return `<div class="section-head"><div><div class="eyebrow">${n}</div><h2>${title}</h2><p>${desc}</p></div>${link?`<a class="text-link" href="${link}">${label} ←</a>`:''}</div>`}
function journeyCard(j){const p=state.journeys[j.id]||{};let done=Array.isArray(p.done)?p.done.length:0;return `<a href="#/journey/${j.id}" class="journey-card"><span class="num">0${JOURNEYS.indexOf(j)+1}</span><h3>${j.title}</h3><p>${j.subtitle}</p><span class="muted">3 محطات · أسئلة فهم · حفظ محلي</span><div class="progress-track"><span style="width:${done/3*100}%"></span></div><span class="text-link">${done===3?'راجع الرحلة':done?'تابع رحلتك':'ابدأ الرحلة'} ← <small>${done}/3</small></span></a>`}
function home(){main.innerHTML=`<section class="hero"><div class="hero-content reveal"><div class="eyebrow">أطلس التاريخ التفاعلي <span class="latin"> / ATLAS</span></div><h1>التاريخ ليس مجرد أحداث…<br>إنه عالم ينتظر أن <em>تكتشفه.</em></h1><p>اعبر العصور، استكشف الحضارات، وافهم كيف ارتبطت قصص الإنسان بالأماكن التي عاش فيها.</p><div class="actions"><a class="primary" href="#/encyclopedia">ابدأ الاستكشاف <span>←</span></a><a class="secondary" href="#/atlas">استكشف الخريطة <span>⌖</span></a></div></div><div class="hero-bottom"><span></span><span class="coords" dir="ltr">A JOURNEY THROUGH HUMAN HISTORY</span></div></section><div class="intro-line"><span><b>${String(civs.length).padStart(2,'0')}</b> موضوعات حضارية</span><span><b>${String(FRAMES.length).padStart(2,'0')}</b> لقطات زمنية</span><span><b>${String(JOURNEYS.length).padStart(2,'0')}</b> رحلات تعليمية</span><span>كل موضوع يبدأ بسؤال وينتهي بفهم.</span></div>
<section class="container section">${sectionTitle('01 / عبر الزمن','كل عصر… نافذة إلى عالم آخر.','اختر حقبة، ثم تتبع الحضارات والمواقع المرتبطة بها.')}<div class="era-list">${[['01','العالم القديم','1400 ق.م',-1400],['02','العصر الكلاسيكي','400 ق.م — 117 م',-100],['03','العصور الإسلامية','632 — 1000 م',650],['04','عصر المغول والمماليك','1300 م',1300],['05','بدايات حديثة','1750 م',1750]].map(x=>`<a class="era" href="#/atlas?frame=${FRAMES.indexOf(x[3])}"><span class="era-number">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]} ←</small></a>`).join('')}</div></section>
<section class="container section" style="padding-top:15px">${sectionTitle('02 / قصص الحضارات','حضارات صنعت التاريخ',`${civs.length} بابًا إلى السياسة والفن والمعرفة والحياة اليومية.`,'#/encyclopedia','الموسوعة كاملة')}<div class="civ-grid">${civs.map(card).join('')}</div></section>
<section class="map-feature section"><div class="container">${sectionTitle('03 / المكان والزمان','العالم عبر الزمن','حرّك الزمن. اختر مدينة. اكتشف القصة.','#/atlas','افتح الأطلس')} ${mapShell(false)}</div></section>
<section class="container section">${sectionTitle('04 / نقاط التحول','أحداث غيّرت العالم','افهم الحدث في سياقه: أين وقع، وماذا تغير بعده؟','#/encyclopedia?type=event','كل الأحداث')}<div class="events-list">${items.filter(x=>x.type==='event').slice(0,3).sort((a,b)=>a.start-b.start).map(x=>`<a class="event-card" href="${href(x.id)}"><span class="date">${escape(x.periodLabel)}</span><h3>${escape(x.title)}</h3><p>${escape(x.summary.slice(0,140))}…</p><span class="text-link">اكتشف الحدث ←</span></a>`).join('')}</div></section>
<section class="container section" style="padding-top:10px">${sectionTitle('05 / تعلّم بالاستكشاف','رحلتك أعمق من قراءة مقال','محطات قصيرة، روابط على الخريطة، وأسئلة تتأكد بها من فهمك.','#/journeys','جميع الرحلات')}<div class="journey-grid">${JOURNEYS.map(journeyCard).join('')}</div></section>
<section class="container section"><div class="city-feature"><div class="city-art">${citySVG()}</div><div><div class="eyebrow">06 / مدن لها حكاية</div><h2>بغداد.<br>مدينة دائرية، وأثر يتجاوز الحدود.</h2><p>ادخل المدينة الدائرية التي بناها المنصور سنة 762 م، واضغط معالمها لتكتشف قصرها وجامعها وأبوابها الأربعة.</p><a class="primary" href="#/city">ادخل المدينة <span>←</span></a></div></div></section>
<section class="container section" style="padding-bottom:20px">${sectionTitle('07 / تحدَّ نفسك','هل تعرف متى ولمن؟','لعبتان قصيرتان: رتّب الأحداث زمنيًا، أو اختر الحضارة صاحبة الحدث.','#/play','كل الألعاب')}<div class="journey-grid"><a class="journey-card game-card" href="#/play/order"><span class="num">⧗</span><h3>رتّب الزمن</h3><p>أربعة أحداث مبعثرة؛ رتّبها من الأقدم إلى الأحدث.</p><span class="text-link">العب ←</span></a><a class="journey-card game-card" href="#/play/owner"><span class="num">◈</span><h3>لمن هذا الحدث؟</h3><p>عشرة أسئلة سريعة عن الحضارات وأحداثها.</p><span class="text-link">العب ←</span></a></div></section><section class="container section"><div class="fact"><span class="fact-mark">“</span><div id="fact-box"></div></div></section>`;renderFact();mountMap(false)}
const FACTS=[['لم تكن اليونان القديمة دولة واحدة.','كانت مئات المدن المستقلة، لكل منها حكومتها وجيشها، وأشهرها أثينا وإسبرطة.','greece'],['جيش من نحو ثمانية آلاف جندي من الطين يحرس قبر أول إمبراطور للصين.','اكتُشف قرب شيآن سنة 1974 م، ولكل جندي ملامح مختلفة.','qin-shi-huang'],['في سنة 929 م كان في العالم الإسلامي ثلاث خلافات في وقت واحد.','العباسية في بغداد، والفاطمية في شمال أفريقيا، والأموية في قرطبة.','cordoba-caliphate'],['بُنيت بغداد الأولى على شكل دائرة.','في وسطها قصر الخليفة والجامع، وحولها أسوار بأربعة أبواب.','baghdad'],['كلمة «خوارزمية» جاءت من اسم عالم عمل في بغداد.','هو محمد بن موسى الخوارزمي، في القرن التاسع الميلادي.','translation-movement'],['حكمت امرأة مصر ملكًا كامل الألقاب قبل 3500 عام.','هي حتشبسوت، وتُظهرها تماثيلها بلحية الملك الرسمية.','hatshepsut'],['أول إمبراطور روماني وُلد خارج إيطاليا هو تراجان.','وُلد في إيطاليكا بإقليم هسبانيا، وفي عهده بلغت الإمبراطورية أوسع امتداد لها.','trajan'],['مدينة واحدة كانت عاصمة لإمبراطوريتين.','القسطنطينية: عاصمة الروم من 330 م، ثم عاصمة العثمانيين من 1453 م.','constantinople-1453'],['تحتفل السعودية بيوم التأسيس في 22 فبراير.','تذكيرًا ببداية حكم الإمام محمد بن سعود في الدرعية سنة 1727 م.','saudi-found']];let factIdx=Math.floor(Math.random()*FACTS.length);
function renderFact(){const box=document.getElementById('fact-box');if(!box)return;const[f,t,id]=FACTS[factIdx%FACTS.length];box.innerHTML=`<div class="eyebrow">08 / هل تعلم؟</div><h3>${f}</h3><p>${t}</p><div class="actions"><a class="text-link" href="${href(id)}">اقرأ القصة ←</a><button class="fact-next" type="button">معلومة أخرى ↻</button></div>`;box.querySelector('.fact-next').onclick=()=>{factIdx++;renderFact()}}
function atlasShell(){return `<div class="ax"><div class="ax-stage"><div id="map" class="map-canvas" role="region" aria-label="الخريطة الجغرافية للمواقع التاريخية"></div><div class="ax-top"><div class="ax-era"><small id="ax-era-name"></small><output id="year-label" for="year-slider"></output><small id="map-tag" class="ax-tag"></small></div><div class="ax-layers" role="group" aria-label="طبقات الخريطة"><label><input data-layer id="layer-city" type="checkbox" checked><span>المدن</span></label><label><input data-layer id="layer-event" type="checkbox" checked><span>الأحداث</span></label><label><input data-layer id="layer-borders" type="checkbox" checked><span>الحدود</span></label></div><div class="ax-styles" role="group" aria-label="نمط الخريطة"><button type="button" data-theme="dark">داكن</button><button type="button" data-theme="parch">ورقي</button><button type="button" data-theme="terrain">تضاريس</button></div><label class="ax-cmp"><span>قارن الحدود مع</span><select id="cmp-year" aria-label="قارن مع حدود سنة أخرى"><option value="">لا شيء</option>${BORDER_YEARS.map(y=>`<option value="${y}">${dateLabel(y)}</option>`).join('')}</select></label></div><div class="map-legend" id="map-legend"></div><div class="ax-dock timeline-controls"><div class="timeline-line"><button id="map-play" class="map-play" aria-label="تشغيل الزمن تلقائيًا">▶</button><button data-frame-move="-1" aria-label="الفترة السابقة">→</button><input id="year-slider" type="range" min="0" max="${FRAMES.length-1}" step="1" value="${mapIndex}" aria-label="اختر لقطة تاريخية" aria-valuetext="${dateLabel(FRAMES[mapIndex])}"><button data-frame-move="1" aria-label="الفترة التالية">←</button></div><div class="frame-list">${FRAMES.map((y,i)=>`<button data-frame="${i}" class="${i===mapIndex?'active':''}">${dateLabel(y)}</button>`).join('')}</div></div></div><aside class="map-side ax-side" aria-live="polite" id="map-side"></aside></div><div class="container"><details class="map-about"><summary>ⓘ عن هذه الخريطة: مواقع موثقة وحدود تقريبية</summary><p>${FRAMES.length} لقطات زمنية مختارة، لا بيانات لكل سنة. العلامات مواقع مدن وأحداث تقريبية. الحدود الملونة تقريبية من مشروع Historical Basemaps المفتوح، وتُعرض لسنة قريبة من اللقطة مكتوبة على الخريطة؛ المشروع نفسه يصف بياناته بأنها قيد التطوير، فلا تعاملها كمرجع دقيق. لا تتوفر حدود لبعض اللقطات. اليابسة والتضاريس والأنهار من Natural Earth بصورتها المعاصرة. <a class="text-link" href="#/sources">المنهجية ←</a></p></details></div>`}
function mapShell(full){if(full)return atlasShell();return `<div class="${full?'full-map':''}"><div class="map-layout"><div class="map-stage"><div id="map" class="map-canvas" role="region" aria-label="الخريطة الجغرافية للمواقع التاريخية"></div><div class="map-top-tag" id="map-tag">مواقع موثقة</div><div class="map-legend" id="map-legend"></div></div><aside class="map-side" aria-live="polite" id="map-side"></aside></div><div class="timeline-controls"><div class="timeline-line"><button id="map-play" class="map-play" aria-label="تشغيل الزمن تلقائيًا">▶</button><button data-frame-move="-1" aria-label="الفترة السابقة">→</button><output id="year-label" for="year-slider"></output><input id="year-slider" type="range" min="0" max="${FRAMES.length-1}" step="1" value="${mapIndex}" aria-label="اختر لقطة تاريخية" aria-valuetext="${dateLabel(FRAMES[mapIndex])}"><button data-frame-move="1" aria-label="الفترة التالية">←</button></div><div class="frame-list">${FRAMES.map((y,i)=>`<button data-frame="${i}" class="${i===mapIndex?'active':''}">${dateLabel(y)}</button>`).join('')}</div><details class="map-about"><summary>ⓘ عن هذه الخريطة</summary><p>${FRAMES.length} لقطات زمنية مختارة، لا بيانات لكل سنة. العلامات مواقع مدن وأحداث تقريبية. الحدود الملونة تقريبية من مشروع Historical Basemaps المفتوح، وتُعرض لسنة قريبة من اللقطة مكتوبة على الخريطة؛ المشروع نفسه يصف بياناته بأنها قيد التطوير، فلا تعاملها كمرجع دقيق. لا تتوفر حدود لبعض اللقطات. اليابسة والتضاريس والأنهار من Natural Earth بصورتها المعاصرة. <a class="text-link" href="#/sources">المنهجية ←</a></p></details></div></div>`}
function activePoints(){let year=FRAMES[mapIndex],q=document.getElementById('map-query')?.value||'',cityOn=document.getElementById('layer-city')?.checked!==false,eventOn=document.getElementById('layer-event')?.checked===true;let cs=activeAt(civs,year).filter(c=>!q||normalize([c.title,byId(c.cityId)?.title].join(' ')).includes(normalize(q)));let points=cityOn?cs.map(c=>({id:c.cityId,title:byId(c.cityId)?.title||c.title,point:c.point,civ:c.id,type:'city'})):[];if(eventOn)points.push(...items.filter(x=>x.type==='event'&&x.point&&x.start<=year&&cs.some(c=>c.id===x.civId)).map(x=>({...x,civ:x.civId})));return points}
function collideGeo(){const mk=[];for(const m of markers){const el=m.getElement();mk.push(el.getBoundingClientRect());const sp=el.querySelector('span');if(sp&&sp.style.visibility!=='hidden')mk.push(sp.getBoundingClientRect())}const hit=(r,v)=>r.left<v.right+2&&r.right>v.left-2&&r.top<v.bottom+2&&r.bottom>v.top-2;for(const g of geoMarkers){const e=g.getElement();e.style.visibility='';if(e.style.display==='none')continue;const r=e.getBoundingClientRect();if(mk.some(v=>hit(r,v)))e.style.visibility='hidden'}}
function collideBorders(){collideGeo();if(!borderMarkers.length)return;requestAnimationFrame(()=>{const box=document.getElementById('map')?.getBoundingClientRect();if(!box)return;const occ=[document.getElementById('map-tag'),document.getElementById('map-legend'),...document.querySelectorAll('.ax-top,.ax-dock'),...geoMarkers.map(m=>m.getElement()).filter(e=>e.style.display!=='none'&&e.style.visibility!=='hidden')].filter(Boolean).map(e=>e.getBoundingClientRect()),hit=(r,v)=>r.left<v.right+4&&r.right>v.left-4&&r.top<v.bottom+4&&r.bottom>v.top-4;for(const m of markers){const el=m.getElement();occ.push(el.getBoundingClientRect());const sp=el.querySelector('span');if(sp&&getComputedStyle(sp).display!=='none'&&getComputedStyle(sp).visibility!=='hidden')occ.push(sp.getBoundingClientRect())}for(const bm of borderMarkers){const e=bm.getElement();e.classList.remove('collide');bm.setOffset([0,0]);if(e.style.display==='none')continue;const r0=e.getBoundingClientRect();let ok=null;for(const [dx,dy] of [[0,0],[0,-28],[0,28],[0,-54],[0,54],[-40,0],[40,0]]){const r={left:r0.left+dx,right:r0.right+dx,top:r0.top+dy,bottom:r0.bottom+dy};if(r.left>=box.left&&r.right<=box.right&&r.top>=box.top&&r.bottom<=box.bottom&&!occ.some(v=>hit(r,v))){ok=[dx,dy,r];break}}if(ok){bm.setOffset([ok[0],ok[1]]);occ.push(ok[2])}else e.classList.add('collide')}})}
function declutter(){if(!liveMap)return;const pos=[];for(const m of markers){m.setLngLat(m.getLngLat());const b=liveMap.project(m.getLngLat()),n=pos.filter(q=>Math.hypot(q.x-b.x,q.y-b.y)<34).length;m.setOffset(n?[16,-14-(n-1)*22]:[0,0]);pos.push(b)}requestAnimationFrame(()=>{const mapEl=document.getElementById('map');if(!mapEl||!liveMap)return;const box=mapEl.getBoundingClientRect(),dots=markers.map(m=>m.getElement().getBoundingClientRect()),seen=[],tagR=document.getElementById('map-tag')?.getBoundingClientRect(),hit=(r,v,g=3)=>r.left<v.right+g&&r.right>v.left-g&&r.top<v.bottom+g&&r.bottom>v.top-g;markers.forEach((m,i)=>{const el=m.getElement(),s=el.querySelector('span');if(!s)return;s.style.visibility='';const r=s.getBoundingClientRect(),ev=el.classList.contains('event');const bad=seen.some(v=>hit(r,v))||(ev&&(dots.some((d,j)=>j!==i&&hit(r,d,1))||r.left<box.left||r.right>box.right||r.top<box.top||(tagR&&hit(r,tagR))));if(bad)s.style.visibility='hidden';else seen.push(r)});collideBorders()})}
